                var rawList=addList;addList=(blocks,module)=>{if(module!=0)blocks.Insert(0,new ApuBlock{Address=MusicTransitions.Start,Chunk=reset});rawList(blocks,module);};
            }
            foreach(var replacement in project.Sounds){NativeSound slot=sounds.FirstOrDefault(s=>s.Wave==replacement.Wave);Bin.Require(slot!=null&&replacement.Data!=null&&replacement.Data.Length>=12&&(replacement.Data.Length-3)%9==0&&replacement.Data.Length<=(slot.Turbo?3321:slot.Bytes),"Invalid or oversized native sound replacement.");byte[] data=replacement.Data;Bin.Require(data[0]==0&&data[1]==0&&data[2]==64,"Invalid native waveform header.");for(int p=3;p<data.Length;p+=9)Bin.Require((data[p]>>4)<=12&&((data[p]&3)==0||p+9==data.Length),"Invalid native BRR block.");Bin.Require((data[data.Length-9]&1)!=0,"Native sound has no end block.");rom.Budget.SampleMax=Math.Max(rom.Budget.SampleMax,data.Length);if(slot.Turbo){int address=store(data,true);foreach(int effect in slot.Effects){Pointer(turbo,effect*6+1,address);Bin.W16(turbo,effect*6+4,data.Length);}changedTurbo=true;}else{int id=addChunk(data,true);commonExtra.Add(new ApuBlock{Address=slot.Address,Chunk=id});byte[] loopPointer=new byte[2];Bin.W16(loopPointer,0,slot.Address+3);commonExtra.Add(new ApuBlock{Address=0x1f00+slot.Wave*4+2,Chunk=addChunk(loopPointer,true)});}}
