            int listAddress=store(CompactLists(target,lists),false),chunkAddress=store(chunks,false);Redirect(rom.Bytes,target,AudioRom.ListAddress(rom.Bytes),listAddress);Redirect(rom.Bytes,target,AudioRom.ChunkAddress(rom.Bytes),chunkAddress);Redirect(rom.Bytes,target,AudioRom.ChunkAddress(rom.Bytes)+2,chunkAddress+2);Redirect(rom.Bytes,target,AudioRom.ChunkAddress(rom.Bytes)+3,chunkAddress+3);
