            if(rom.Project.CampaignSlots!=null&&rom.Project.CampaignSlots[0]!=0)Buffer.BlockCopy(target,RomLayout.At(target,AudioRom.SongTable)+rom.Project.CampaignSlots[0]*2,target,RomLayout.At(target,AudioRom.SongTable),2);
        }
    }
